 "<b style=\"font-size:26px;color:#ca7334\">Límites de tiempo</b><br><span style=\"font-size:21px;color:#14293a\">Horarios configurados en el dispositivo.</span>": "<b style=\"font-size:26px;color:#ca7334\">Limites de temps</b><br><span style=\"font-size:21px;color:#14293a\">Horaires configurés sur l’appareil.</span>",
